def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    extracted_groups = []  # Initialize an empty list to store the extracted groups
    start_index = 0
    end_index = 0

    while end_index < len(paren_string):
        if paren_string[end_index] == '(':
            count = 1
            end_index += 1
            while count != 0:
                if paren_string[end_index] == '(':
                    count += 1
                elif paren_string[end_index] == ')':
                    count -= 1
                end_index += 1
            extracted_groups.append(paren_string[start_index:end_index])
            start_index = end_index
        else:
            end_index += 1

    return extracted_groups

